def transform(grid):
    H=len(grid); W=len(grid[0])
    seeds={(r,c):grid[r][c] for r in range(H) for c in range(W) if grid[r][c] not in (0,1)}
    def nonzero(r,c):
        return 0<=r<H and 0<=c<W and grid[r][c]!=0
    # 4-conn components over nonzero cells, each seed forces its color
    color={}
    import collections
    seen=set()
    for sr,sc in seeds:
        if (sr,sc) in seen: continue
        q=collections.deque([(sr,sc)]); seen.add((sr,sc)); comp=[(sr,sc)]
        while q:
            r,c=q.popleft()
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                n=(r+dr,c+dc)
                if n not in seen and nonzero(*n):
                    seen.add(n); q.append(n); comp.append(n)
        for r,c in comp: color[(r,c)]=seeds[(sr,sc)]
    out=[row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            if grid[r][c]==1 and all(nonzero(r+dr,c+dc) for dr in(-1,0,1) for dc in(-1,0,1)):
                out[r][c]=color[(r,c)]
    return out
